enum IncidentStatus { pending, verified, responding, resolved, closed, rejected }
class ResidentIncident { final String ticketId; final String type; final String barangay; final String status; final String reportedAt; final String priority; const ResidentIncident({required this.ticketId, required this.type, required this.barangay, required this.status, required this.reportedAt, required this.priority}); factory ResidentIncident.fromJson(Map<String, dynamic> json) => ResidentIncident(ticketId: json['tickets']?['ticket_number'] ?? json['ticket_id'] ?? 'Processing', type: json['incident_type'] ?? '', barangay: json['barangay'] ?? '', status: json['status'] ?? 'pending', reportedAt: json['reported_at'] ?? '', priority: json['priority'] ?? 'low'); }
